<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\SoftDeletes; use Illuminate\Database\Eloquent\Relations\{BelongsTo,HasMany};
class PurchaseOrder extends Model { use SoftDeletes; protected $fillable=['purchase_order_number','supplier_id','order_date','expected_delivery_date','status','notes','subtotal','discount','tax','total']; protected $casts=['order_date'=>'date','expected_delivery_date'=>'date','subtotal'=>'decimal:2','discount'=>'decimal:2','tax'=>'decimal:2','total'=>'decimal:2']; public function supplier():BelongsTo{return $this->belongsTo(Supplier::class);} public function items():HasMany{return $this->hasMany(PurchaseOrderItem::class);} public function receipts():HasMany{return $this->hasMany(GoodsReceipt::class);} }
